// ---------------------------------------------------------------- Professionals
function pro(r: R): GuideSection[] {
  return [
    {
      id: "join", title: "Joining Nearest", icon: "sparkle", topics: [
        { q: "How do I put Nearest on my home screen?", a: ["Nearest installs like an app. A banner shows the way for your phone: tap Install (Android Chrome), or on iPhone tap Share (the square with an arrow) in Safari → Add to Home Screen → Add. If you opened Nearest from Instagram, Facebook or TikTok, open it in Safari or Chrome first — apps can't install from inside those. Tapped Not now? It comes back in 14 days, or use the steps above anytime."] },
        { q: "Trouble signing in? (\"You are signed out\")", a: ["That means this browser's saved login is out of sync — usually on a computer. 1) Make sure your computer's date and time are set automatically (the sign-in screen warns you if the clock is off). 2) Clear this site's cookies for usenearest.com, or try a private/incognito window. 3) If incognito works, an ad blocker or privacy extension is blocking the login — allow usenearest.com. Still stuck? Use \"Email me a code\" instead of your password, or contact support."] },
        { q: "Can I sign in without my password?", a: ["Yes. On the sign-in screen, enter your email and tap \"Email me a 6-digit code instead\" — type the code and you're in, no password needed. Or sign in with your password (8 or more characters). Forgot it? Tap Forgot password to set a new one."] },
        { q: "Nearest set up my profile for me — what do I do?", a: ["Open the link in the email we sent you and create a password (8 or more characters). You're signed straight in. Before anything else you'll see your profile and the Professional Terms — read them and tap Accept and go live. Your profile is switched on right away; verify your ID next, and students can find and book you as soon as Nearest confirms it. It's your account from then on: change anything in Business, and go offline from Today whenever you like. The link works once and lasts 14 days — if it expired, ask the person who set you up to send a new one."] },
        { q: "How long do I have to finish registering?", a: [`${r.holdDays} days from creating your professional account. Within that time, accept the Professional Terms, send your ID check or submit your profile. If none of those happen, registration for your account closes and you're placed on the waiting list — you'll see "Enrollment is closed for now" when you sign in.`, "Nothing is deleted: your profile, photos and services stay saved. When Nearest reopens enrollment for you, you'll get an email (and a notification) and can pick up where you left off, with a fresh " + r.holdDays + " days. The same applies to an invitation or registration link that isn't used within " + r.holdDays + " days."] },
        { q: "What does it cost?", a: [`Nothing to join and nothing monthly. There's no sign-up fee, no monthly membership and no card needed — being on Nearest is free.`, `Each completed booking (services and Model Calls) has a $5 booking fee. It's added on top of your price, so students see one total and you receive your full price. Card processing comes out of each payment.`, `Spots are limited in each city, for each category: the first ${r.firstInPerCategory} professionals are First In, the next ones (up to ${r.perCategory}) join next, and after that new professionals can join a free waitlist. On the Join page, enter your ZIP code and main category to see your spot.`, "Spots are for professionals taking bookings: if your profile isn't live within 30 days of joining for reasons on your side, your spot may be released (we remind you a week before, and time Nearest spends reviewing never counts). You can reclaim it from your home screen if your city still has room."], link: { label: "Fees & payouts", href: "/pro/payments" } },
        { q: "How do add-ons work?", a: ["In Services & prices, open a service and tap \"+ Add an add-on\" — for example \"Rhinestones\" +$10 and +15 minutes, or \"Charms\" +$5. Add up to 10 per service, each $1–$100 with 0–180 extra minutes.", "Students tick the add-ons they want when booking: the price is added to the service and the extra minutes are added to the appointment, so your calendar blocks the right amount of time. Your booking shows exactly what they ordered (e.g. \"Short French Set + Rhinestones\").", "There's no Nearest service fee on add-ons — you receive their full price (minus card processing). A booking can't be more than $150 for the student including add-ons, so the editor shows how much room each service leaves."] },
        { q: "Can I add a photo to a service?", a: ["Yes — under each service in Services & prices, tap \"Add a photo of this service\". It's optional and shows next to that service on your profile, so clients see your work for exactly what they're booking.", "Everything starts minimized. Tap a category (for example \"Braids — 3 services\") to expand it; only one opens at a time. Inside, each service is one short line (photo, name, the price students see, minutes) — tap Edit to change it, then Minimize. After you save, use View my profile or Back to my account menu."] },
        { q: "What name do I put as my legal name?", a: ["Your legal first and last name exactly as they appear on your driver's license or state ID — never your business name. \"Kweenz Nailz\" or \"Tasha Lashes\" can't be a legal name: words like Nails, Lashes, Beauty, Studio, Glam or LLC (including spellings like Nailz) aren't accepted, and neither are numbers, emoji or symbols.", "Your business name goes on your profile (Business → Profile). It can include your own name — \"Nails by Tasha\" or \"Heather's Lashes\" is fine — but your legal name can't be your business name or a word taken from it. If your account's legal name is wrong, email support@usenearest.com and Nearest will correct it."] },
        { q: "Why do I verify my ID during setup?", a: ["It secures your account and protects your clients. Verify your identity is the step right before Review & submit: a photo of your driver's license or state ID and a live selfie. Nearest checks they match; your ID is never shown publicly. Anything left to finish shows on Today with a Finish button that takes you straight there."] },
        { q: "What am I responsible for as a professional?", a: ["The Professional Terms you accept on the last setup page cover it. Section 5: you must hold every license, permit and qualification the law requires for the services you list (your professional status is self-reported). Section 6 — Liability, insurance & indemnity: you're responsible for the services you provide and their results (including reactions or injuries); follow sanitation and safety rules and do patch tests where appropriate; carry professional and general liability insurance; tell Nearest within 48 hours if a license is suspended, revoked or expired; respond to client complaints through Nearest; and cover Nearest for claims that come from your services.", "When the terms are updated, a card on your home screen asks you to read and accept the new version. You can see which version you accepted under Subscription."] },
        { q: "When am I charged?", a: ["Never. Joining, building your profile and staying listed are free — there's no monthly fee. Each completed booking has a $5 booking fee (added on top of your price, so it's part of the student's total), and card processing comes out of each payment."] },
        { q: "What's the $5 booking fee?", a: ["Each service has a $5 booking fee, always added on top of your price — a $30 service shows students $35, and you receive your $30. You don't choose it per service; under each price you'll see what students pay. Students see one total, never a separate fee. The fee applies only to completed bookings. Your appointment shows the fee line so you always know your take-home. It applies to Model Calls too: your model price + the fee is what models see."] },
        { q: "Why are there two names and two pictures?", a: ["Clients want to know who they're booking. Your profile shows your own name (for example \"Jasmine C.\") with a photo of you, and your business name with your logo underneath. Set both in Business → Profile."] },
        { q: "How do booking requests work?", a: ["Every booking starts as a request. You'll get a notification, an email and — if you turned them on — a phone alert. If you haven't answered after an hour (30 minutes when the appointment is within 12 hours), you get one reminder the same ways. Open it from Today or Appointments and tap Accept booking or Decline. You have 24 hours (or until 2 hours before the appointment). After you accept, the student pays to confirm; the appointment is confirmed when they pay, and you'll be told if they don't pay in time. Declining doesn't count against you. Accepting never charges you anything."] },
        { q: "How do I get phone alerts for new bookings?", a: ["Turn on Phone alerts (the card on Today, or Notifications at the top of Today → the bell). New booking requests, reminders, messages and other Nearest notices then pop up on your phone like a text — free, no texting plan needed. Each phone or computer is turned on separately, and you get a test alert right away.", "iPhone: first add Nearest to your Home Screen (in Safari tap Share → Add to Home Screen → Add), open Nearest from that icon, then turn on alerts (needs iOS 16.4 or newer). Android: works in Chrome — installing Nearest to the home screen is recommended.", "Not getting them? If you tapped Don't Allow, turn notifications on for Nearest in your phone's settings, then come back. Emails keep coming either way — add hello@usenearest.com to your contacts so they don't land in spam or Promotions."], link: { label: "Turn on phone alerts", href: "/pro/notifications" } },
        { q: "How do I go live?", a: ["Use the Go live card on Today (also in Business). It lists anything still left; once everything's done, tap Go live and you show up in search, Near Me and All professionals. Tap Go offline anytime to hide.", "Payouts are never required to go live — anything you earn is held for you and sent once you connect your bank.", "Go live within 30 days of joining to keep your city and category spot."], steps: ["Finish your profile setup and submit it.", "Nearest approves your profile.", "Your ID check is approved.", "Tap Go live."], link: { label: "Today", href: "/pro/home" } },
        { q: "What if Nearest sends something back?", a: ["If Nearest can't approve your profile or ID check, you'll get an email and a notification with the exact reason and a button straight to the screen where you fix it. Your Today screen also lists it until it's fixed. Everything else you've done stays saved."] },
        { q: "What if my city is full?", a: [`Every city — in every state — opens each service category with ${r.firstInPerCategory} spots. Your spot is counted when you tap Submit profile on the last setup step (and always while you're live), in each category you have a service in. When a category's spots are taken, enrollment closes for that category in that city: join the free waitlist and you'll be told if spots open. Nearest may open one more round of ${r.perCategory - r.firstInPerCategory} later — never more than ${r.perCategory} in total — so a reopening isn't guaranteed.`] },
        { q: "What is the ID check?", a: ["Upload a photo of your driver's license or state ID and take a live selfie. A Nearest team member reviews it, usually within a day. If something's unclear, you'll be asked to send new photos."], link: { label: "ID & payments", href: "/pro/payments" } },
        { q: "What's Professional status?", a: ["One quick question for your whole account: I have my license, Graduated — license pending, Currently enrolled in school, or I'm self-taught. Pick one and continue — no license numbers, schools or documents, nothing to review, and it's never shown on your profile. Change it anytime in Business → Professional status. Under the Professional Terms you're responsible for being legally qualified for every service you offer."] },
      ],
    },
    {
      id: "setup", title: "Your profile", icon: "user", topics: [
        { q: "What is Professional Protection?", a: ["Nearest is exploring affordable insurance for independent beauty and wellness professionals through a licensed insurance partner. On the last setup page (or on your home screen if you registered earlier) you'll see three choices: I already have insurance, I'm interested in insurance through Nearest, or Not interested right now. If you're interested, pick pay-per-booking coverage, annual coverage, or more information first.", "The two models being explored are about $3 per eligible booking (you'd pay only when you work, per covered appointment) or about $49 a year (one payment covers your services for 12 months). These are proposed, unconfirmed prices — not insurance you can buy yet and not a quote. Answering is optional, costs nothing, and never affects your registration or bookings. We never ask for your insurer, policy number, dates or documents.", "Change your answer anytime: Business → Professional Protection. Your Professional Terms (section 6) still ask you to carry professional and general liability insurance."], link: { label: "Open", href: "/pro/protection" } },
        { q: "What do students see next to my name?", a: ["A green shield next to your name (your profile was approved and your ID checked), and under your name — on your profile and your search card — every kind of service you offer — taken from the services you have turned on, so add a service in each category you do.", "Until you get your first verified review, your profile says \"New Professional\". After your first client reviews a finished appointment, it shows your star rating instead — there's no time limit; it's your first review that changes it."] },
        { q: "What is a Nearest Partner page?", a: ["A link-in-bio page for beauty educators and creators at usenearest.com/link/your-name: your photo, name, rating and social links, a Book an appointment button, up to 4 top services, Model Calls, Bundle my booking, your Learn with me videos and your shop links, plus a Save to my phone button. Booking happens in normal Nearest booking.", "Apply at usenearest.com/partners with the email you sign in with. Once Nearest approves you, open Business → Partner page: add a headline, pick your top services, add links (title, web address, optional note — up to 12) and video links (YouTube, TikTok, Instagram or Vimeo — up to 12), and turn on Page is live. Your photo, name, social links, services and prices come from your profile, so edit those in Business. The page shows once your profile is approved; until you're live in search, it says booking opens soon.", "Copy your link from the top of Partner page and put it in your Instagram and TikTok bio. Clients who tap Save to my phone get your page on their home screen like an app, with your photo as the icon. Nearest can pause a partner page."], link: { label: "Open Partner page", href: "/pro/partner" } },
        { q: "Nearest set up my partner page — what do I do?", a: ["Open the link in the email from Nearest and create a password (8 or more characters). What happens next depends on the link: Set up my profile or Finish my profile takes you through the setup steps that are left, then you submit your profile. Review and approve my page shows your profile and a preview of your partner page — accept the Professional Terms and tap Approve my page and go live.", "Once you approve, your link to share appears at the top of Business → Partner page (and in your email). Put it in your Instagram and TikTok bio. Sign in any time at usenearest.com/pro/sign-in with your email and password, or have a code emailed to you; Forgot password lets you set a new one. You can change anything on your page after you approve."], link: { label: "Open Partner page", href: "/pro/partner" } },
        { q: "How do I sell downloads and products on my partner page?", a: ["Business → Partner page → My shop → Products. Add a product and choose Digital download (a workbook, guide, template, preset, video — upload the file: PDF, ZIP, EPUB, MP4, MP3 or image, up to 200 MB) or Physical product (shampoo, tools, flat irons, lash kits — set the shipping price and, if you like, how many you have). Add a name, description, price and photo, and tick Show in my shop. Up to 24 products.", "Your products show in a Shop section on your partner page. Buyers don't need a Nearest account: they tap Buy, pay with Stripe, and a digital download appears on screen with a Download now button and in their email right away (the link works a set number of times for a set period). Your download file is never shown on your page.", "Physical orders appear under My shop → Orders with the buyer's name and shipping address (never their email). Ship it, add the carrier and tracking if you have them, and tap Mark shipped — the buyer is emailed and you're paid. Digital sales are paid out right after payment. Card processing comes out of each sale, plus Nearest's order fee if one is shown in My shop. You need payouts connected (Business → Fees & payouts) before your shop takes orders. Can't ship an order? Contact Nearest support before marking it shipped and the buyer is refunded."], link: { label: "Open My shop", href: "/pro/partner/shop" } },
        { q: "A Nearest rep sent me a link — what is that?", a: ["Nearest has sales reps who share their own sign-up link with professionals. Signing up through a rep's link is the same Nearest account with the same free sign-up — the rep just gets credit for introducing you. Reps can see your business name and how far along your profile is, never your bookings, earnings, clients or contact details.", "Reps are independent and can't change prices, promise you clients or make deals for Nearest. If something a rep told you doesn't match what you see in the app, the app is right — contact support@usenearest.com."] },
        { q: "What are the setup steps?", a: ["Everything is under Business, and you can edit any of it later."], steps: ["Profile & photo — business name, bio, photo, Instagram/TikTok/Facebook/Pinterest links, and your booking link name.", "Services & prices — pick your category, tap a service (or + Add custom service), then fill in Your price ($) and How long (minutes, numbers only — 90, not 1 hr 30). Students see your price plus the $5 booking fee, up to $150; mark any 18+ only.", "Location & travel — your address, whether you travel, how far, and your travel fee.", "Hours — choose Regular hours, After-school hours, or Both, then set the days and times for each.", "Communication & accessibility — languages, ASL, how clients should reach you.", "Portfolio — up to 10 photos and 5 videos (15 seconds max), each tagged with a service.", "Licenses — then preview and submit."], link: { label: "My business", href: "/pro/business" } },
        { q: "Do I have to finish setup in one sitting?", a: ["No. Every step has Save & finish later — it saves what you've done and takes you to Today, where Continue setup picks up right where you left off. On Services, even half-finished services are kept as a draft. If you're away a while, we'll send a reminder."] },
        { q: "Is my address private?", a: ["Yes. Students only see how far away you are. A booked student sees your address at 12:00 AM on the appointment day, and only they see it."] },
        { q: "I'm moving to a different city. Can I transfer?", a: ["Yes. Update your address in Location & travel. If your new city has room in your category, you move right away. If it's full, saving sends Nearest a transfer request (add a note like \"I moved and work from home now\"). You stay listed in your current city until it's approved, and your fees stay the same. You'll get an email and a notification either way."], link: { label: "Location & travel", href: "/pro/setup/location?edit=1" } },
        { q: "How does the travel fee work?", a: ["If you travel to clients, set a flat fee from $35 to $55 in Location & travel. It's only added when the student chooses to have you come to them. The $150 limit applies to the service, not the travel fee."], link: { label: "Location & travel", href: "/pro/setup/location?edit=1" } },
        { q: "What does 18+ only do?", a: ["Tick 18+ only under a service and Nearest blocks anyone under 18 from booking it, using their verified birthday. You still follow your own licensing rules."] },
        { q: "How do I make my portfolio book for me?", a: ["Show up to 10 photos and 5 videos (15 seconds max each — MP4, or straight from your phone's camera). Tag each one with the service it shows, and students can tap \"Book this look\" to book that exact service. Star your best work so it shows first."], link: { label: "Portfolio & social", href: "/pro/setup/portfolio?edit=1" } },
        { q: "How do students find me by photo?", a: ["Students can upload an inspo photo with Find by photo. Nearest compares it with the photos in your portfolio and shows you only when one of your photos closely matches that exact look — so your portfolio is what gets you found.", "Upload clear, close-up photos of your own finished work (one look per photo, good light, no heavy filters, text or collages) and tag each with its service so a matching student can tap Book this look. New photos are added to matching within about 15 minutes. Videos aren't used for matching."], link: { label: "Portfolio & social", href: "/pro/setup/portfolio?edit=1" } },
        { q: "What's my booking link?", a: ["Every pro gets a link like usenearest.com/pro-yourname. Put it in your Instagram, TikTok, Facebook and Pinterest bio or send it in DMs — it opens your profile so students can book. You can change the name in Profile & photo."], link: { label: "Today", href: "/pro/home" } },
      ],
    },
    {
      id: "calendar", title: "Hours, calendar & openings", icon: "cal", topics: [
        { q: "How do students see my availability?", a: [`On the Hours step you choose Regular hours, After-school hours (weekdays after school), or Both — change it anytime from Calendar → Weekly hours → Edit. Students can only book times inside the hours you set that aren't already booked or blocked. Normal bookings need ${r.advance} hours' notice, so you won't get surprise bookings.`], link: { label: "Calendar", href: "/pro/calendar" } },
        { q: "How do I block time or take a vacation?", a: ["In Calendar, use Block time for appointments outside Nearest, breaks or errands — the note is only for you. Turn on Vacation mode to hide all openings and Model Calls from new bookings."] },
        { q: "What is Available Today?", a: [`It's how you fill same-day gaps. Pick the times you're free today and publish — students see an Available Today badge on your profile. Same-day booking closes at ${r.cutoff}, and students need to book at least ${r.sameDayNotice} hours ahead. Uncheck every time and publish to clear them.`], link: { label: "Available Today", href: "/pro/today" } },
      ],
    },
    {
      id: "modelcalls", title: "Model Calls", icon: "sparkle", topics: [
        { q: "What is a Model Call?", a: ["A discounted spot for practicing a new technique or building your portfolio. Students see it in Model Calls near me and on your profile.", "Model Calls are bookings too, so the $5 booking fee is added to your model price the same way as your services: a $15 model price shows models $20, and a free model call shows $5. You receive your model price (minus card processing)."], link: { label: "Model calls", href: "/pro/model-calls" } },
        { q: "How do I post one?", a: [], steps: ["Choose the service, price, length and how many spots.", "Pick a set date and time — or Open time, so models choose a time from your hours until the call closes.", "Add requirements, a photo of the look and any extra information.", "Publish. When all spots are taken, it shows as full."] },
        { q: "Can I cancel or delete a Model Call?", a: ["Tap Cancel model call on an upcoming one. Past or cancelled calls can be deleted to tidy your list."] },
      ],
    },
    {
      id: "appts", title: "Appointments", icon: "clock", topics: [
        { q: "Launch campaign — do I give anything?", a: [`No. Students who complete Nearest's seven-day launch promotion get ${r.campaignCredit} in Nearest credit from Nearest. They use it like money toward any of your services when they book you, and you're paid your normal price — nothing comes out of your payout for it. There's nothing to sign up for or choose.`] },
        { q: "How does an appointment work?", a: ["Everything happens on the appointment's page."], steps: ["The student checks in when they arrive — you get \"Your client has checked in.\"", "Tap Start service. A timer runs while you work.", "Tap Finish service & send completion steps.", "The student confirms, adds a photo and review, and releases payment."], link: { label: "Appointments", href: "/pro/appointments" } },
        { q: "What if my client doesn't show?", a: [`If they haven't checked in after the ${r.grace}-minute grace period, you can mark a no-show. You keep the ${r.deposit} deposit, and the rest becomes credit the student can only use with you.`] },
        { q: "What if they leave without finishing?", a: [`Nearest applies the completion policy: if they don't finish within ${r.completionHours} hours of you tapping Finish, you're paid automatically.`] },
        { q: "What if I have to cancel?", a: ["The student gets the full amount back as Nearest credit, and it counts toward your cancellation rate. Cancel only when you truly have to."] },
        { q: "How do I message clients?", a: [`Each appointment has its own chat, open for ${r.msgDays} days after the appointment. Phone numbers and emails are never shared.`], link: { label: "Messages", href: "/pro/messages" } },
        { q: "What's a Bundle Me booking?", a: ["Students can bundle several services for the same week (for example hair, lashes, nails and makeup) within a budget. When one of those bookings is with you, you get a notification and the appointment is marked \"Part of a Bundle Me booking.\" It's a normal paid booking — the student pays your full price, and credits and invite rewards can't be used on it."] },
        { q: "What's the $5 student invite reward?", a: ["Students who invite friends to Nearest earn $5 off. When a student uses it on their first booking with you, they pay $5 less and your payout for that booking is $5 less. You agreed to this when you joined — it's how Nearest rewards students for sharing the platform, and it keeps you booked. It never applies twice for the same student with you, and never to Model Calls. You'll see it on the appointment."] },
        { q: "How do reviews work?", a: ["Only students who completed an appointment with you can review you, so every review is real. Ratings help you rank in search."] },
        { q: "Where do my clients' photos go?", a: ["Every client takes a photo of their finished look. It goes to your private Client photos — never straight into your portfolio. From there you choose: show it with that client's review, add it to your portfolio, download it to your phone, or remove it. Showing or adding only works if the client allowed sharing."], link: { label: "Client photos", href: "/pro/client-photos" } },
      ],
    },
    {
      id: "money", title: "Getting paid", icon: "wallet", topics: [
        { q: "When do I get paid?", a: ["The student pays in full when they book. Nearest holds it until they release it at the end of the appointment. Then it goes to your bank through Stripe, minus card-processing fees. Stripe sets the bank transfer timing."], link: { label: "Earnings", href: "/pro/earnings" } },
        { q: "How do I set up payouts?", a: ["Go to Payments and connect your bank through Stripe. You can be bookable before this — anything you earn is held for you and sent automatically once you connect."], link: { label: "Payments", href: "/pro/payments" } },
        { q: "Why do I get a reminder about payouts when I accept a booking?", a: ["Until your payout account is set up, every booking you accept comes with a reminder (a notification, an email and a note on the appointment) so you don't miss getting paid. Nearest holds your money safely until payouts are connected — set them up in Payments and the reminders stop."], link: { label: "Set up payouts", href: "/pro/payments" } },
        { q: "What do Pending release and Released mean?", a: ["Pending release is money from appointments the student hasn't released yet. Released is money that's on its way to, or already in, your bank."] },
        { q: "What's in Updates?", a: ["Business → Updates lists changes to how Nearest works that you need to acknowledge — for example an update to the Professional Terms. It shows how many are waiting.", "Tap Open to read one: it shows what changed and the full Professional Terms. It stays open until you scroll through, tick the box and tap Acknowledge and accept — then it's done and the list says you're all caught up. New professionals accept the current terms when they submit their profile, so they won't have any."], link: { label: "Updates", href: "/pro/updates" } },
        { q: "Where are my fees and payouts?", a: ["Business → Fees & payouts shows that there's no monthly fee, your ID check, and your payout setup."], link: { label: "Fees & payouts", href: "/pro/payments" } },
      ],
    },
    {
      id: "standing", title: "Rules, fines & account status", icon: "shield", topics: [
        { q: "What gets a pro fined?", a: [`When Nearest confirms an on-site problem was the pro's fault, there's a ${r.fine} fine due in ${r.fineDue} days, and the student gets a full credit. Every ${ordinal(r.incidentLimit)} confirmed incident also suspends your profile for ${r.proSuspDays} days.`] },
        { q: "What if a fine goes unpaid?", a: [`Your profile is hidden until it's paid. After ${r.unpaidDays} days unpaid, Nearest may review whether to remove your account.`] },
        { q: "Where do I see my standing?", a: ["Business → Account status shows your fines, suspensions, confirmed incidents and reviews. You can pay a fine there or request a review of a fine or suspension."], link: { label: "Account status", href: "/pro/account-status" } },
        { q: "How do I delete my account?", a: ["Business → Delete account (owners see Remove my professional business). You can't delete while you have upcoming appointments or unpaid fines."] },
        { q: "Something isn't working.", a: ["If something breaks, Nearest can send a problem report with a screenshot in one tap. Or email support@usenearest.com."] },
      ],
    },
  ];
}

// ---------------------------------------------------------------- Admin
function admin(r: R): GuideSection[] {
  return [
    {
      id: "overview", title: "Overview", icon: "home", topics: [
        { q: "Command Center", a: ["Today at a glance: professionals, bookings today, professional MRR, and everything that needs attention — invitations waiting and students, pros and licenses to verify."], link: { label: "Open", href: "/admin" } },
        { q: "First In", a: [`First In pros who joined against the ${r.firstIn}-seat limit, invitation codes, and the enrollment phase (First In open, First In closed, or next entry open with Professional + Student and General). Only owners can change the phase. You set each invitation's expiration date and time when you create it, and invitations don't need a city.`, "The main owner also sees Special invitation: Ambassador (a guaranteed spot even when their city and category is full, and they share the main owner's link, so pros they bring in are credited to the main owner — everyone is free to join now). Only the main owner can create these, and they work even when First In is closed."], link: { label: "Open", href: "/admin/founding" } },
        { q: "Service coverage", a: [`The recruiting map: For every city: how many professionals Nearest has in each category, how many are live, and how many more are needed to fill the ${r.firstInPerCategory} spots each category opens with (or ${r.perCategory} once you've authorized the additional opening). It also shows First In progress, progress toward the market goal of ${r.marketGoal.toLocaleString()} professionals, and a Recruit next list — the biggest gaps in the cities with the most verified students. Tap a city for its full breakdown.`], link: { label: "Open", href: "/admin/service-coverage" } },
        { q: "Coverage", a: [`Every market's counties and cities, which cities have a live pro, and verified students. The goal is ${r.perCity} pros per city. Add cities by State + ZIP.`], link: { label: "Open", href: "/admin/coverage" } },
      ],
    },
    {
      id: "people", title: "People", icon: "users", topics: [
        { q: "Launch campaign (elapsed-time tracking + manual evidence review)", a: ["Students see the campaign invitation automatically once after registration (on Explore, only while the campaign is open, for DFW-school students who haven't joined). It shows the reward (Nearest credit — the amount is set in Rules & Settings → Fees → Launch campaign reward), the credit terms, the How to participate steps (the Instructions field in Settings — one step per line), the username + profile-picture screenshot rule and the key points. JOIN THE CAMPAIGN leads to the agreement checkbox; NOT NOW hides the invitation for good (the Account card stays). Unverified students see their remaining step instead of a join button; when full they see JOIN THE WAITLIST with a note that it doesn't reserve a reward.", "People → Launch campaign shows the status in large letters — DRAFT, LIVE, PAUSED or CLOSED — with Go live, Pause and Stop (close enrollment). Go live stays greyed out until the checklist under it is done (graphic, published terms, the How to participate steps and the booking-opening date). The page also shows counts (reserved, active, ready for final review, approved — credit added, cancelled, waitlist), filters by status, platform, city and county, and the waitlist. Owners set capacity, the booking-opening date/time, the steps, terms (published versions), and the graphic in Settings.", `The reward is ${r.campaignCredit} in Nearest credit, funded by Nearest. Approving a participant adds it to their account automatically, once (general credit usable with any professional, not on Bundle Me). Professionals don't give free services and aren't asked to opt in — they're paid their normal price when a student uses the credit. Anyone approved before this change gets their credit added automatically.`, "Each participant's record shows live eligibility, the social profile with Open social profile, the seven-day clock (start, required completion = start + 168 hours, live countdown, seven daily windows with Submitted/Missing, each screenshot's server upload time, final-proof status) and one chronological timeline of screenshots, profile checks and actions.", "Record profile check saves who checked, the server time, whether the Nearest picture was visible, and notes. The clock never approves anyone: after 168 hours the status becomes Ready for final review. Approve requires the full 168 hours, a final screenshot, the student still eligible, no other reward, and a tick if any daily windows are missing — and it adds the credit right away. If someone else changed the record while you were looking, your action is refused — reload and try again. Request correction, Don't approve (optionally releasing the place) and Cancel entry all need a reason and notify the student."] },
        { q: "Supporters (educator endorsements)", a: ["People → Supporters. Tap Invite a supporter to make a private link that expires (14 days by default, 1–60). Nothing is sent automatically — tap Copy link and share it yourself. Each link takes one submission; you can cancel unused links. Statuses: Invited, Submitted, Needs correction, Approved, Published, Declined, Withdrawn.", "Explainer video: upload a short video (or paste a YouTube/Vimeo link) on the Supporters page. It plays at the top of the form so supporters can see what Nearest offers students and parents without making an account.", "Narrated walkthrough: a 3:29 tour of the real app — registration and enrollment verification, finding nearby professionals, after-school hours, services, student prices, portfolios and hours, Favorites, Model Calls, Bundle my booking for prom, homecoming and school pictures on a budget, booking (shown as a preview), protected payments, check-in, in-app messages, finishing and releasing payment, Report a problem, Connections and sharing a professional, the $5 invite reward, and the launch campaign free service, recorded with demonstration accounts and sample data — no real students, bookings or payments. It has captions and a transcript and never plays sound on its own. Preview it on the Supporters page, then tap Publish it on the invitation page (owner only) — it then shows just above the feedback form. Tap Hide it to take it down.", "The supporter fills in a short form inside Nearest (no account): name, private contact email, role (Teacher, Principal, Administrator or School Counselor), whether they're currently with a school/organization, are a former employee or affiliate of one, or neither (and which one), optional photo, their thoughts and overall impressions of Nearest and/or how it could benefit students and parents (both with example text — answering one is enough; if they answer only the second, it becomes their statement), a 1–5 star rating of Nearest (nothing preselected), what they reviewed, personal vs. organizational endorsement, and any relationship with Nearest. Submitting includes their agreement to publish — there are no separate publish choices. New submissions show in your notifications bell.", "Their star rating and review are saved in Nearest and shown on /supporters (with the average rating). After submitting, supporters with no paid, benefit or work tie to Nearest see an optional Copy my review & open Google button — it copies their review and opens Nearest's Google review page so they can paste it there too. Google only lets people post reviews themselves, so it can't be posted or copied for them, and Google doesn't allow reviews from people Nearest compensated or rewarded.", "Review shows everything, including the original opinion statement (never changed). Approve, Request correction (note shown on their link), or Decline (reason), then Publish. An organizational endorsement is labeled as one only if they're currently with the organization, confirmed authorization AND you confirm it when approving — a school name alone never counts.", "Want different wording? Suggest it — it's used only after the supporter approves it on their management link. Supporters use that link to correct their answers (it goes back to review and comes off the page) or withdraw (removed immediately). Lost link? Issue a new one (the old stops working).", "Public pages show only Published supporters, with one statement each: initials when there's no photo, \"formerly with\" for past affiliations, a Personal endorsement label and any relationship disclosure. With none published, the homepage section is hidden. Contact emails are never shown. These are separate from student reviews and pro ratings."], link: { label: "Open", href: "/admin/supporters" } },
        { q: "Students", a: ["Every student account, their school and verification status, suspensions, and account actions.", "Each student shows as Verified Student or Nearest Alumni (past their graduation year — same access), and students under 18 show whether their parent approved, is pending, or declined."], link: { label: "Open", href: "/admin/students" } },
        { q: "Schools", a: ["The school directory, plus schools students asked for. Private high schools aren't in the public directories — add them here."], link: { label: "Open", href: "/admin/schools" } },
        { q: "Professionals", a: ["There's no monthly membership (since October 17, 2026): every professional who joined shows \"Joined — no monthly fee\", and nobody is ever asked to activate. Review account shows their Terms version and date, pending booking requests and their first request date.", "Every pro with status, cancel rate and controls. Review account shows exactly what's blocking a pro from going live (profile, ID, payouts), their money and checks, setup, and activity.", "30-day spot rule: a pro who joined 23 days ago and still isn't live for reasons on their side gets a reminder; at 30 days (and at least 6 days after the reminder) their spot is released. Pros waiting on Nearest's review of their profile or ID, owners' businesses, invitation and Ambassador accounts are never released. A released pro can tap Reclaim my spot on their home screen if their city still has room (the 30-day clock restarts).", "Transfer requests show at the top: pros moving to a city that\u2019s full in their category. Approve applies their new location (and tells anyone waiting in their old city that a spot opened); deny sends them your reason. \"Remind everyone who hasn\u2019t finished\" (and \"Send setup reminder\" on a Review account page) emails pros who haven\u2019t submitted their profile — never more than once in 12 hours. Professional status (self-reported, one per account) at the top counts how many pros are licensed, license pending, currently enrolled or self-taught — tap one to filter. Rejected profiles show at the top with the reason — tap Approve to overturn one (or Approve all, owners). When the Professional Terms change, pros who joined earlier find it in Business → Updates (with a count). Opening an update shows what changed and the full terms; it can't be closed until they tick the acknowledgment and accept. New registrations accept the current version when they submit, so they never get an update. Review account shows each pro's accepted version and date."], link: { label: "Open", href: "/admin/professionals" } },
        { q: "Verification Queue", a: ["Approve or reject student IDs, pro IDs (license/state ID + selfie) and pro profiles. Every view of an ID is logged, and student ID photos are deleted on every decision.", "Anything you send back (profile or ID) emails and notifies the pro with your reason and a link to fix it — so keep reasons short and specific. Students who verified by school email show a green \"School email verified\" note. Students whose school doesn't issue IDs show a \"No school ID\" tag with their proof of enrollment (enrollment confirmation, class schedule, student portal screenshot or tuition receipt — photo or PDF; tap Open document for PDFs). Check it shows their name, the school they chose and current enrollment; financial and unrelated details may be hidden. Verify student approves (same access and campaign eligibility as a school ID — no ID is asked for later), Reject needs a reason (they start over), and Ask for a clearer document keeps their selfie, deletes the document and notifies + emails them to upload a new one. Professional licenses aren't reviewed — pros self-report their status."], link: { label: "Open", href: "/admin/verification" } },
      ],
    },
    {
      id: "ops", title: "Operations", icon: "cal", topics: [
        { q: "Bookings", a: ["Every booking with status, times, amounts and check-in details."], link: { label: "Open", href: "/admin/bookings" } },
        { q: "Incident Review", a: [`On-site complaints with the timeline (check-in, complaint, service start) and the check-in photo. Confirming professional fault gives the student full general credit, fines the pro ${r.fine} due in ${r.fineDue} days, and every ${ordinal(r.incidentLimit)} confirmed incident suspends them for ${r.proSuspDays} days.`], link: { label: "Open", href: "/admin/incidents" } },
        { q: "Enforcement", a: [`Outstanding and past-due fines, suspended pros and students, and automatic checks. Students are suspended for ${r.studentSuspDays} days after passing ${r.noShowLimit} no-shows. Pros with fines unpaid ${r.unpaidDays}+ days are listed as eligible for removal — nothing happens automatically; decide case by case.`], link: { label: "Open", href: "/admin/enforcement" } },
        { q: "Appeals", a: ["Review requests from students (suspensions) and pros (fines and suspensions). Uphold or overturn with a decision reason — overturning reverses the action."], link: { label: "Open", href: "/admin/appeals" } },
        { q: "Problem reports", a: ["Automatic error reports from anyone on the site, with a screenshot of what they saw. Each is also emailed to support@usenearest.com."], link: { label: "Open", href: "/admin/reports" } },
      ],
    },
    {
      id: "business", title: "Business", icon: "chart", topics: [
        { q: "Nearest logo in email inboxes (BIMI)", a: ["The Nearest monogram is published at usenearest.com/bimi-logo.svg in the format inboxes require. It applies to every @usenearest.com sender — all partners, outreach, broadcasts and notifications — once the DNS records in docs/BIMI-SETUP.md are added. Yahoo, AOL and Fastmail show it for free; Gmail and Apple Mail also need a paid logo certificate."] },
        { q: "Professional Outreach", a: ["Each partner works their own recruiting here and sees their own results; the main owner can switch to Everyone. Your recruiter link is at the top of the Outreach dashboard — every professional who joins through it (from outreach, Facebook groups, QR codes, anywhere) is credited to you.", "Add prospect adds one professional; Bulk import reads Excel, CSV, Word or PDF lists (or a pasted list) and shows a review screen first — nothing is contacted until you approve. Nearest checks every partner's prospects, existing accounts and the do-not-contact list, so one professional is only ever worked once.", "When a prospect creates a Nearest account they're marked Registered automatically and never recruited again; submitting their profile marks them Profile complete. Markets shows how full each city's categories are — the same count the Join page enforces — so you know what to prospect next. ", "Templates is where you write exactly what goes out: the first email and two follow-ups, with fill-ins like {first_name}, {city}, {category} and {link} (their personal invite, good for 24 hours and credited to whoever owns the prospect). Preview them, email yourself a test, and add your mailing address (required by law — nothing sends without it).", "Queue is where emails start: create a batch from your Ready prospects (filter by city or category), start now or schedule a date, and pause, resume or cancel anytime. Emails go out every 15 minutes; follow-ups go 3 and 7 days later (change in Rules & Settings → Outreach) and stop automatically when someone joins, unsubscribes or you pause them. Owners also have Pause all outreach. Replies go to the outreach reply address — pause that prospect while you answer. You'll get a bell alert when your queue drops to 15 or fewer.", "The AI recruiter answers replies to the outreach reply address for you. It only uses the How Nearest works professional guide, live spots and prices for that prospect's city and category, your approved answers and your playbook — it never guesses. When someone's interested it sends their personal invite link. Anything it can't answer goes to Needs review (with a bell alert) after it sends your holding reply; answer it there and tick \"Save as an approved answer\" so it handles that question next time. \"Stop\" or \"unsubscribe\" replies are honored instantly.", "The AI answers normal questions on its own — what is this, how it works, cost, who it's for, how to sign up, is it in my area, is this legit, where did you find me — and only sends to Needs review when someone asks for a person, needs a decision or exception, or asks something it truly doesn't have. Every Needs review item says why it's there (for example \"AI key missing\" or \"the AI turned it over: asked about a refund\"). Use Answer with AI to have it reply once the reason is fixed, and Test the AI (on the AI recruiter page) to check it's connected without emailing anyone.", "AI recruiter (in Outreach) is where you edit its playbook, never-say rules, holding reply and approved answers, and see whether it's connected. Conversations shows every reply; on a prospect you can read the whole thread, reply yourself, or Take over so the AI stops answering them (Hand back to the AI anytime).", "Broadcasts (owners) send one email to a group: professionals (all, live, unfinished profiles, waiting for their city), prospects (active, emailed, no response, joined) or students, narrowed by city or category. You'll see the exact number of recipients and a preview before you tap Send; it goes out in batches every 15 minutes. Unsubscribed and do-not-contact emails are skipped, and a broadcast never changes anyone's recruiting status.", "Reports show the funnel — added, emailed, replied, links clicked, joined, profile complete — with rates, by recruiter, source, city and category, for today, this week, this month or all time. Use it to see which sources actually produce professionals."], link: { label: "Open", href: "/admin/outreach" } },
        { q: "Enrollment limits and the additional opening", a: [`Same rule in every city and state: each service category opens with ${r.firstInPerCategory} professional spots. When they're taken, enrollment closes for that category in that city — new professionals join the waitlist, and nothing reopens on its own. An owner can authorize ONE additional opening of ${r.perCategory - r.firstInPerCategory} for a specific city and category (Outreach → Markets → tap the city → Authorize the additional opening), for at most ${r.perCategory}. It can't be undone, and everyone on that waitlist is told spots opened (first come, first served). No setting can go above 10. Invitation codes, owners and Nearest-managed accounts are exempt.`], link: { label: "Open Markets", href: "/admin/outreach/markets" } },
        { q: "Add prospects from screenshots", a: ["Outreach → Add from screenshots. Upload 1–5 screenshots of ONE professional — their Instagram or Facebook profile, link-in-bio, booking page or business flyer (anything showing their name, business, location and contact details). Screenshots uploaded together go into one form. Nearest reads the text right in your browser — no AI service and no API key; the reader is part of Nearest itself — and fills in what's visible: name, business, main service category (matched to Nearest's list), other services, credentials as they state them, street address, city, state and ZIP, email, phone, Instagram handle, Facebook page, profile link, website, booking link, hours, listed service prices and any deposit (kept separate from service prices). It never makes up details that aren't visible — anything it can't read is left blank for you. If the county isn't shown, it's looked up from the city or ZIP and marked for you to confirm.", "Where they were found is set to Instagram or Facebook only when the screenshots clearly show it (for example an Instagram profile with posts, followers and following); otherwise it's left as Not sure for you to choose. If the screenshots show different details for the same field (two phone numbers, say), the draft lists them at the top so you can pick the right one. Need another screenshot? Use Add more screenshots on the draft — it only fills empty fields, keeps everything already in the form (including your corrections) and notes any different detail for you to check.", "Each upload becomes a draft in Waiting for your review — nothing is added to your prospects or contacted yet. Open a draft to see the screenshots next to the details, fix anything, and Save changes. The draft shows what's still needed (name, category, city, county, state, where they were found and at least one way to reach them). When everything is right, tap Approve and add to my prospects: it becomes your prospect (your referral attribution), Ready for outreach if it has an email, or Needs information if it doesn't. If the person is already in Outreach, already a Nearest professional, or on the do-not-contact list, the draft says so and can't be approved — Discard it (that also deletes its screenshots). If a screenshot can't be read (blurry, cut off, or an unusual layout), the draft is still created with the screenshots so you can type the details. You see your own drafts; the main owner sees everyone's."], link: { label: "Open", href: "/admin/outreach/screenshots" } },
        { q: "Build a profile for a professional", a: ["Outreach → Build a profile (owners). For professionals who gave you permission to set them up. One form, and everything extra is optional: add 1–5 screenshots (their profile, link-in-bio, booking page or flyer) and tap Read screenshots — the text is read on your device and fills in their name, email, phone, business, main category and city, and saves their address, Instagram, website, listed prices (as unfinished services to check) and licensed status straight onto the profile. Add their photo and business logo right there too. No screenshots? Just type their legal name, the email they'll sign in with, and pick their category and city (type the first letters of the city — Texas is chosen by default; switch the state beside it for anywhere else) (or open a prospect and tap Build their profile for them — it fills these in and links the prospect, which stops recruiting emails). The city must have room in that category. Tap Create and start building: the photo, logo and screenshots upload, and you're taken to the first setup step that's still missing, acting as them, with a gold banner on top — everything you save goes on their profile. You can build the whole profile for them: Profile (photo, logo, About me), Services & prices (screenshot prices are already there — add the length), Professional status, Location, Hours, Communication and Portfolio photos. Partners: their Partner page and Shop too. Then they only set a password and look it over — they can change anything later. Their screenshots and the details read from them stay on their Build a profile page to copy from. Tap Back to admin when you're done; you can come back anytime with Continue building.", "Don't know their street address? Leave it blank on Location (keep the city and ZIP) — they're asked for it when they sign in, before they go live. When everything but the ID is done, send the link: Email the link, or Copy the link to text or DM it to them yourself (the link shows with a Copy button either way). Their screenshots stay private in Admin — the professional never sees them. They open it, create a password (8+ characters), are signed straight in, see their profile and the Professional Terms, and Accept and go live puts the profile live immediately — no separate review. They verify their own ID (the selfie must be them) and set up their own payouts; you can't do those, accept the Terms, or take bookings for them. They can go offline anytime. The link works once and lasts 14 days; sending a new one replaces it. If email isn't working, the link is shown so you can text it. Status on the list: Building → Link sent → Password set → Accepted (waiting on their ID) → Live. The partner who builds it gets the credit. While First In's 750 still has room, every profile you build joins as First In (with every First In benefit) — even past the first spots in its city and category; the city + category limit still applies. The profile page shows \"Joins as First In\" before you send the link. Their legal name must be the name on their government ID — never their business name or anything made from it (screenshot details can mix these up, so check). The form refuses business words like Nails, Lashes, Beauty, Studio or LLC in a legal name."], link: { label: "Build a profile", href: "/admin/outreach/build" } },
        { q: "Service add-ons", a: ["Professionals can list optional add-ons under any service (Services & prices → + Add an add-on): name, price ($1–$100) and extra minutes (0–180), up to 10 per service. Students tick add-ons when booking; the price and length are added to the booking, and the booking's service name lists them (e.g. \"Short French Set + Rhinestones\") everywhere it appears — bookings, earnings, receipts.", "The $150 student limit covers the service plus the chosen add-ons (a travel fee stays separate). No Nearest service fee is taken on add-ons. Refunds, credits, deposits and payouts all use the booking's full price, so add-ons follow the same rules as the service."] },
        { q: "Insurance interest", a: ["Business → Insurance interest. Every professional's answer to the Professional Protection question: name, insurance preference (already have insurance / interested through Nearest / not interested right now / not answered yet), the coverage model they're interested in (pay per booking, annual, or more information first), when they registered and when they answered. Filter by preference or model; the totals at the top add it up.", "New professionals see the question on the last setup page (optional — it never blocks submitting). Professionals who registered earlier get a card on their home screen until they answer, and anyone can change it under Business → Professional Protection.", "It's self-reported only: no insurer names, policy numbers, expiration dates, documents, verification or approvals. The ~$3 per eligible booking and ~$49 a year models are proposals for a future licensed insurance partner, who would handle quotes, premiums, policies and coverage confirmation — nothing is charged or deducted until a partner agreement and integration are approved."], link: { label: "Open", href: "/admin/insurance" } },
        { q: "Outreach meetings (book a meeting with the Director of Outreach)", a: ["Professional Outreach → Outreach meetings (owners only). Copy your booking link (usenearest.com/meet) and send it to nail techs, lash artists, hairstylists and barbers. Nobody needs a Nearest account to book.", `They choose their city first (Lewisville, Flower Mound, The Colony, Highland Village, Double Oak, Copper Canyon, Bartonville, Carrollton, Coppell or Frisco), then their specialty — each city has ${r.meetSpots} spots per specialty, and a full specialty closes there — then licensed / in school / self-taught and whether they're home-based.`, `Times: meetings are ${r.meetMinutes} minutes. Start times run from the first start time with ${r.meetTravel} minutes of travel after every meeting, nothing during the midday break, never on the no-travel day, and the last start time is always offered. Any time that would leave you less than ${r.meetTravel} minutes to get to the next meeting (in any city) disappears. If you're already meeting people in their city, the same day is offered first; they can take it or pick another day.`, "Where: Meet at my location (their address — only you see it) is the default; a Starbucks in their city is the other option. Add Starbucks locations on this page (one per line: Name | Address); a city with none shows that none are listed.", "They upload their photo and give their legal name, business name, phone and email. They can bring a friend, who must be a nail tech, lash artist, hairstylist or barber, gives their own details and photo, and takes one of the spots — no fill-ins. Before booking they check a box agreeing the booking can't be changed and that missing it means they can't book again.", "You get a bell notice and an email for every booking; they get a confirmation email and can add it to their calendar. On this page: upcoming meetings by day with photos, Mark showed up, Mark no-show (that email and phone can't book again), Cancel meeting (frees the time and spot), Undo, and the spots-filled grid. Change the times, break, day off, travel time and spots in Rules & Settings → Outreach meetings. Every action is saved to the activity log."], link: { label: "Open Outreach meetings", href: "/admin/meet" } },
        { q: "Partner pages (Nearest Partners)", a: ["Professional Outreach → Partner pages (owners only). Three links to share, each with Copy and Open: the partner link (usenearest.com/partners — what the program is, both demos and the application form), the client demo (usenearest.com/partners/demo — link page, booking profile, booking, Bundle my booking, Model Calls, shop, save to phone) and the setup demo (usenearest.com/partners/demo/setup — apply, sign in, page & links, services, portfolio, travel & hours, shop, share). The demos use sample data and fit any screen.", "Applications (name, email, Instagram, city, specialty, what they teach) arrive under New and ring the bell; the applicant gets a confirmation email with both demo links. Approve emails them: if a professional account already uses that email, their partner page opens in their pro app (Business → Partner page) with an inbox notice; if not, they're told to create a professional account with that same email and the page appears once they do. Decline emails them (with your optional note). Move back to New undoes either.", "Partner pages lists every approved partner: Live, Hidden by them, Waiting for profile approval, or Paused, with their link. Pause page hides it from the public right away; Resume turns it back on. Partner pages are separate from Sales Track partner codes. Booking from a partner page uses normal Nearest booking. Every decision is saved to the activity log."], link: { label: "Open Partner pages", href: "/admin/partners" } },
        { q: "Adding a partner yourself (setup, finish or approve link)", a: ["Partner pages → Partners you added → + Add a partner. Fill in their legal name, email (their sign-in), phone, business name, Instagram, main category and city, plus optional screenshots, photo and logo. They're approved as a partner right away — no application — and they stay on Partner pages, never in Outreach.", "Pick how their profile gets done. They set up everything themselves: their setup link is emailed right away. You start it, they finish: build what you can (the same setup pages, plus Business → Partner page for links, videos and shop), then tap Send link: they finish setting up. You finish it, they approve: build all of it, then tap Send link: they review and approve (it only sends once every setup step is done). Switching someone who already has an account (for example a free Ambassador): Professionals → open them (Review account) → Nearest Partner → Switch to a Nearest Partner account. Their profile, bookings, sign-in and free status stay the same; a partner page is added and they're told by email and in the app. They then show under Partners you added. Each link has Email it and Copy link to text or DM — copy puts it on your clipboard and shows it, so you can send it to them directly. Each new link replaces the old one.", "Every link works once and lasts 14 days; sending a new one replaces the old one, and the message after you send shows the link so you can DM or text it too. With the setup or finish link they create a password and go through the normal setup pages, then submit their profile for review (approve it in the Verification Queue). With the approve link they create a password, see their profile, can preview their partner page, accept the Professional Terms and tap Approve my page and go live — their page goes live, their share link appears in the app and is emailed to them with the sign-in link (usenearest.com/pro/sign-in; Forgot password resets it). You get a bell when they approve.", "If the email already belongs to a professional on Nearest, they're made a partner on their existing account (no new profile or link) and told by email and in the app. Each partner shows their status: You're building it, Link sent, Link expired, Setting up their profile, Password set — hasn't approved yet, Submitted, Live. Every step is saved to the activity log."], link: { label: "Open Partners you added", href: "/admin/partners?view=added" } },
        { q: "Partner shop (downloads and products)", a: ["Partners sell digital downloads and physical products from their partner page (Business → Partner page → My shop). Buyers check out with Stripe without a Nearest account. Digital: a download link is shown on screen right after payment and emailed (Rules & Settings → Partner shop sets how many downloads and how many days it works); the seller is paid right away. Physical: Stripe collects the US shipping address, the seller sees name + address in Orders, marks it shipped (tracking optional, the buyer is emailed) and is paid then. Sellers need payouts connected before their shop takes orders; money earned before payouts are on is held and sent when they connect.", "Admin → Professional Outreach → Partner pages → Shop orders lists the last 50 orders with what was paid, what the seller gets and the payout status. Refund buyer (owners) refunds the card for any order the seller hasn't been paid for yet (an unshipped product) — the buyer is emailed, stock is put back, and it's saved to the activity log. Once a seller is paid, they refund the buyer directly.", "Rules & Settings → Partner shop: Nearest's fee per order (starts at $0, taken from the seller's payout), the highest product price, downloads allowed per purchase, and days a download link works. Card processing always comes out of the seller's side."], link: { label: "Open Partner pages", href: "/admin/partners" } },
        { q: "Sales reps: Campaign Guide and dashboard demo", a: ["Every rep's dashboard (/rep) has a Campaign Guide: a campaign planner (focus area, up to 3 service categories, timeframe, goal — saved on their own device only), how a campaign works, where to find professionals online and in person, approaching professionals, approaching beauty and trade schools (adults who run the programs only — never high schools or anyone under 18), campaign ideas, Meta and Google ads (only with Nearest's written approval, per the Sales Ambassador Agreement), copy-ready messages with the rep's link filled in (DM, email, in-person pitch, follow-up, text, school call and email, three captions), brand rules, tracking tips and Follow Nearest (Facebook and Instagram). The text lives in src/lib/rep-campaign.ts.", "The rep dashboard also shows professionals by status — Started, Profile complete, Live, First booking — and sign-ups by city and by service category. Reps have their own How it works guide at /rep/guide.", "To recruit reps, send the rep dashboard demo: usenearest.com/reps/demo — sample rep, sample professionals and sample numbers only, clearly labeled as a demo. It is separate from the partner program and its link is on the Sales Board."], link: { label: "Open the rep demo", href: "/reps/demo" } },
        { q: "Find by photo", a: [`Students tap Find by photo on Explore and upload an inspo photo. Nearest only shows live professionals in the student's market whose own portfolio photos closely match that look — never someone just because they list the service.`, `How it works: every portfolio photo is fingerprinted on Nearest's own server (whole photo plus close-up areas; new photos within about 15 minutes, videos are skipped). The student's photo is compared with those fingerprints, the closest photos (Rules & Settings → Find by photo → shortlist) are checked by the AI side by side with the inspo photo, and only scores of ${r.matchMin} out of 10 or higher are shown — ${r.matchVery} and up is labeled Very close match. Without the AI key, only near-identical photos are shown. The AI uses the same ANTHROPIC_API_KEY as the AI recruiter.`, `Students' photos are never stored. Each student gets ${r.matchDaily} searches a day (Rules & Settings → Find by photo). Operations → Find by photo shows how many portfolio photos are ready, recent searches (what was detected and how many matches) and, for owners, Add waiting photos now.`], link: { label: "Open Find by photo", href: "/admin/photo-match" } },
        { q: "Enrollment holds", a: [`People → Enrollment holds. Every night Nearest puts these on hold: professional accounts more than ${r.holdDays} days old that never accepted the Professional Terms, never sent an ID check and never submitted their profile — and profiles you built (Build a profile or Add a partner) where the person didn't claim it and accept the Terms within ${r.holdDays} days of the link you sent them (a new link restarts the count; a profile you haven't sent a link for yet is never held); invitation codes never used in ${r.holdDays} days; and outreach registration links never used in ${r.holdDays} days. Anyone who accepted the Terms or sent their ID is never held. Change the number of days in Rules & Settings → Growth.`, "Nothing is deleted. A held professional who signs in, opens setup, registers again with the same email, opens their invitation or their claim link sees: Sorry — enrollment in your area has reached capacity, so registration is closed right now. You've been placed on the waiting list. Each attempt is listed under their name (with the time and what they tried), the Trying to get back in tab shows only those, and you get one bell notice per person per day.", "Owners tap Allow them to finish registering (optional note): they're emailed and notified that enrollment is open for them, an invitation link works again, and they get another full period before the check runs again. For a profile you built that was never claimed, releasing doesn't email them — send them a new sign-in link from their Build a profile page (or Partner pages). While someone is on hold, sending them a link is refused. Put back on hold reverses it. Run the check now runs it immediately. Their Review account page shows a hold banner. Every action is saved to the activity log."], link: { label: "Open Enrollment holds", href: "/admin/enrollment-holds" } },
        { q: "Lead Contributors", a: ["Outreach → Lead contributors (owners only). Invite a person by name and email, copy their invitation link and send it yourself; they create a login with that exact email and land on Professional Prospect Entry (/leads). That page is all they can use — every admin page, student information, payments, supporter submissions, exports and the prospect list stay closed to them, checked on the server. Revoke access turns their login and all their invitation links off immediately; leads they entered stay.", `Where to recruit (/leads/targets for contributors; Outreach → Where to recruit for admins): every one of the 199 cities and towns in the 11 DFW counties (Collin, Dallas, Denton, Ellis, Hunt, Johnson, Kaufman, Parker, Rockwall, Tarrant, Wise) against every service category, using the target of ${r.firstInPerCategory} professionals per category per city in Rules & Settings → Growth. It shows totals, a Categories table (cities filled, cities still open, open spots), and the city list with each city's open spots and status: Needs professionals, In progress, or Filled — move on. Open a city to see exactly which categories it still needs. Filter by county, category, status (still need professionals / filled / all), sort, or search a city. When every category in a city is filled, the city moves to Filled — closed; with a category chosen, a city closes for that category as soon as its spots are taken. It never shows prospects or recruiting results. Every professional counts, however they joined (their own sign-up, any invitation, a sales rep, a partner or a Lead Contributor): from the moment they submit their profile, they take one spot in their city for each category they have an active service in — a pro offering lashes and photography takes a spot in both. Each city needs ${r.firstInPerCategory} professionals in every category (the per-category target in Rules & Settings → Growth); a category is Filled once ${r.firstInPerCategory} are counted there, so one professional shows as 1 of ${r.firstInPerCategory}. The spot is counted when the professional taps Submit profile on the last setup step (anyone already live on Explore always counts) — until then they're listed under the city as signing up, with the categories they're signing up for. Filled here means the recruiting target is met; enrollment itself closes at the cap per category in Rules & Settings → Growth (after that, new professionals join the waitlist). Everyone — owners, admins and Lead Contributors — sees, when they open a city, who is already on Nearest there and in which categories, plus anyone signed up in that city who isn't counted yet and why (hasn't submitted their profile, no active services yet, or their spot was released), and a list of professionals who haven't chosen a city yet — so nobody recruits the same professional twice. It shows names and business names only, never contact details; admins can click a name to open the account.`, "On /leads they can Add a prospect (name, business, service category, city, county and state, email, phone, social profile or website, where they found them, optional notes — name, category, location and at least one way to reach them are required) or Create an invitation link (one per professional, 7/14/30 days). The link opens a public Nearest interest form: no account, and it says plainly it doesn't create an account or reserve a spot. Each link takes one submission. Nothing is ever sent to the prospect automatically. Contributors see only confirmations and their own links — never prospect lists, outcomes or anyone else's activity.", "Attribution: every contributor lead is set on the server to Avy's existing recruiter account and AVY referral code (the same AVY attribution her own leads use). The contributor is recorded separately as Entered by — internal tracking only, with no referral ownership, partner credit or compensation. Method (manual or invitation), invitation, date and time and source are recorded too, and each lead keeps a stable prospect ID. When the prospect registers as a professional, the AVY attribution carries over; if they joined with another partner's code, nothing is overwritten and the lead is flagged as an attribution conflict.", "Duplicates and conflicts: email, phone and social link are checked against every prospect and professional account. A match is saved as a separate Duplicate record linked to the original (the original lead and its history are never changed, and the contributor isn't told). If the match belongs to another recruiter, it's flagged Attribution conflict for Avy to review — open it and tap Mark reviewed. Same name or business in the same city shows Possible duplicate. Leads without an email address are Needs information and are never used for email outreach.", "Only Avy (the leads' recruiter) and the main owner can see these records and their outcomes. Prospects → filter by Entered by, method, flags, city, county, category, status and dates; each lead shows an Attribution box. New statuses: Needs information and Duplicate; Ready for outreach, Invited to register and Not interested are the renamed Ready, Link sent and Declined."], link: { label: "Open", href: "/admin/outreach/contributors" } },
        { q: "Notifications (the bell)", a: ["The bell at the top right counts unread notifications: new professional registrations (with the recruiter), completed profiles, categories that are nearly full or full, and imports that need review. Opening Notifications marks them read; the history stays."], link: { label: "Open", href: "/admin/notifications" } },
        { q: "Money", a: ["Nearest's revenue — the service fee kept on completed bookings, split into services and Model Calls (last 30 days) — kept separate from professionals' money (card payments, held and released funds, and card-processing fees paid by pros)."], link: { label: "Open", href: "/admin/money" } },
        { q: "Sales Track", a: ["Partner progress, the professionals each partner brought in, and partner earnings. Partner earnings are shares of membership payments, so with no monthly membership (since October 17, 2026) they stop as old memberships end — sharing service fees with partners isn't set up yet. Partner links (?ref=CODE) are remembered for 30 days, so partners get credit even if the pro signs up later."], link: { label: "Open", href: "/admin/sales" } },
        { q: "Marketing", a: ["Where to push next: sign-ups by city, verified students, cities below target, and demand without supply (or supply without demand)."], link: { label: "Open", href: "/admin/marketing" } },
        { q: "Bundle Me", a: ["How students use Bundle my booking: bundles started, fully booked, in progress and expired; bundle bookings and what they paid; the most bundled categories; the students using it most; and every recent bundle."], link: { label: "Open", href: "/admin/bundles" } },
        { q: "Leaderboard", a: ["Top pros (overall score, bookings, highest rated, most reviewed, favorited, shared) and top students, for 30 days, 90 days or all time."], link: { label: "Open", href: "/admin/leaderboard" } },
        { q: "Profile examples", a: ["Sample pro and student profiles showing what a fully built-out account looks like. Sample data only — nobody real."], link: { label: "Open", href: "/admin/examples" } },
        { q: "Marketplace", a: ["Change the catalog without a developer: categories, suggested services, and whether a license is required."], link: { label: "Open", href: "/admin/marketplace" } },
      ],
    },
    {
      id: "owner", title: "Owner tools", icon: "gear", topics: [
        { q: "Link previews when you share Nearest", a: ["Any Nearest link you text or post shows the Nearest logo preview. Apps like Messenger and Facebook remember an old preview for a while — if one still shows the wrong picture, paste the link into Facebook's Sharing Debugger (developers.facebook.com/tools/debug) and tap Scrape Again, or add something like &v=2 to the end of the link."] },
        { q: "Why don't some people see \"Install Nearest\"?", a: ["The Install banner appears 3–4 seconds after opening Nearest in a browser, and never once it's installed. iPhones never show a one-tap install — the banner gives Share → Add to Home Screen steps. People who open your link inside Instagram, Facebook or TikTok are told to open it in Safari/Chrome first, since those apps can't install. Anyone who tapped Not now won't see it again for 14 days."] },
        { q: "Sales Board & ambassador Leaderboard (main owner)", a: ["Each ambassador has two personal links: usenearest.com/r/CODE for professionals and usenearest.com/r/CODE/students for students. Every tap is counted, and anyone who signs up within 30 days is credited to them once you've approved their ID.", "The Leaderboard at the top ranks ambassadors by results — pros who submitted a profile plus students who verified — for This week, This month or All time. It also shows taps (pro • student), pros live and activated, and students who booked. \"Links not crediting yet\" means you still need to approve that ambassador's ID (their taps still count). Ambassadors see their own numbers on their Nearest page."], link: { label: "Open", href: "/admin/sales-board" } },
        { q: "Trouble signing in? (\"You are signed out\")", a: ["That means this browser's saved login is out of sync — usually on a computer. 1) Make sure your computer's date and time are set automatically (the sign-in screen warns you if the clock is off). 2) Clear this site's cookies for usenearest.com, or try a private/incognito window. 3) If incognito works, an ad blocker or privacy extension is blocking the login — allow usenearest.com. Still stuck? Use \"Email me a code\" instead of your password, or contact support."] },
        { q: "Launch readiness", a: ["Checks the live settings the site is running with — keys, email, Stripe, and test data. Use \"Clear test Stripe links\" after testing with test keys."], link: { label: "Open", href: "/admin/launch" } },
        { q: "Rules & Settings", a: ["Every number in the rules engine — booking notice, same-day cutoff, when an unanswered booking request reminds the pro (60 minutes, or 30 when the appointment is within 12 hours), grace period, check-in distance, deposit, fines, suspensions, First In capacity and more — plus switches for registration and bookings. Changes are logged, and the guides update automatically."], link: { label: "Open", href: "/admin/settings" } },
        { q: "Public resource center (SEO pages)", a: ["usenearest.com has public pages anyone can read without signing in — built so students, parents and beauty professionals nationwide can find Nearest on Google and in AI search: About, For professionals, Student beauty services, Resources (16 guides), Locations (with a city checker), FAQ (120 answers) and Contact. They never show anything private, and they don't tie Nearest to any one state.", "Numbers on them (service fee, $150 cap, booking notice, deposit, spots per category) come from Rules & Settings, so changing a rule updates the public pages within an hour. Locations lists only cities with at least one live professional. Wording lives in src/content — see docs/SEO-AND-AI-DISCOVERY.md for the Search Console checklist and measurement plan.", "Search engines are always pointed at https://www.usenearest.com (with www) — usenearest.com without www redirects there, so every canonical link, the sitemap and the structured data use the www address, and the Launch readiness page flags APP_URL if it isn't the www address. The sitemap also lists every live professional's public booking page (usenearest.com/pro-name), and the links professionals share use the www address too.", "Bing, Yahoo, DuckDuckGo and ChatGPT search are told about every public page automatically once a day (IndexNow), and about a professional's booking page the moment they go live. Owners can send everything right away from Launch readiness → Search engines → Send all pages to Bing now. Google doesn't use IndexNow — for Google, submit the sitemap and request indexing in Search Console."], link: { label: "Open the resource center", href: "/resources" } },
        { q: "City interest", a: ["Outreach → City interest. Anyone can check a city on usenearest.com/locations: it shows live for bookings, open for professionals (per category), closed at capacity, or not open yet. If they tick the opt-in box, they're saved here by city and role (professional, student, parent) with their main service and the page they came from. Nothing is emailed automatically — use it to decide where to open next and who to contact; tap Mark contacted after you reach out."], link: { label: "Open City interest", href: "/admin/outreach/interest" } },
        { q: "Growth report", a: ["Outreach → Growth report: the last 12 weeks of student sign-ups (and how many are verified), professional sign-ups (and how many came through a partner link or a sales rep), booking requests, completed bookings and city-interest sign-ups. Read it next to Google Search Console: rising search clicks should show up here a few weeks later."], link: { label: "Open Growth report", href: "/admin/outreach/growth" } },
        { q: "Legal name vs business name", a: ["A professional's legal first and last name must match their government ID. Nearest refuses a legal name that is the business name, is built from it (\"Kweenz\" from \"Kweenz Nailz\"), or contains business words (Nails, Lashes, Beauty, Studio, Glam, LLC, stylized spellings like Nailz), numbers, emoji or symbols — at professional sign-up, in Build a profile, and when a professional saves their business name.", "To fix an existing account: Professionals → Review account → Correct legal name. A warning shows there when the current name looks like a business name. Every correction is saved to the activity log."] },
        { q: "Student Pricing Intelligence", a: ["Business → Pricing intelligence: an internal, read-only analysis of real listings and bookings — price distribution, the five price bands (under $50, $50–85, $85–100, $100–149.99, exactly $150) with counts and percentages, average/median/min/max by category, city and state, individual vs Bundle Me bookings, requests → accepted → paid → completed by price range, student spend per completed booking (service, booking fee, add-ons, travel and discounts shown separately), what produces completed bookings, price changes over time, and automated insights.", "Listed prices and completed-booking prices are always kept separate. Groups with fewer than 5 records show \"Insufficient data\"; rates need 10+ requests. Profile views aren't tracked, so they're not shown. Model Calls and free launch-campaign rewards are left out of price analysis. Listed-price edits are recorded from this release on.", "It changes nothing — no prices, rules, rankings or public scores, and the $150 limit stays as it is. Filter by date range, state, city, category and professional."], link: { label: "Open Pricing intelligence", href: "/admin/pricing" } },
        { q: "Public website content audit", a: ["A repeatable check of everything public: it reads the live sitemap, opens every page the way Google sees it, and checks all FAQ entries. It flags the word \"marketplace\", competitor directories or booking apps, advice to list outside Nearest (Google Business Profile, other listings), wording that explains what Nearest earns (fees are only ever called a booking fee), state-centered or dated expansion copy, outdated pricing (monthly memberships, the wrong booking fee or price limit), guarantee claims, missing sign-up or city-checker links, broken internal links, and missing titles, descriptions, canonicals, H1s or structured data.", "Your developer runs it with: npm run content:audit -- https://www.usenearest.com. It writes docs/content-audit-report.md. Run it after any content change and before each release."] },
        { q: "How do professionals hear about a new booking?", a: ["Three ways at once: a notification in Nearest, an email (\"New booking request\"), and a phone alert if they turned on Phone alerts (Today card or Notifications; iPhone needs Nearest on the Home Screen first). If they haven't answered after the reminder time in Rules & Settings, they get one reminder the same three ways. Requests expire after 24 hours or 2 hours before the appointment, whichever is first — the student isn't charged and is told to book someone else. Phone alerts are free and need no setup on Nearest's side."] },
        { q: "Team & Activity Log", a: ["Individual logins for owners and partners (never shared) and the permanent log of every admin action with before and after values."], link: { label: "Open", href: "/admin/team" } },
        { q: "My profile", a: ["Your name, your partner link code, and where your partner payouts go (through Stripe)."], link: { label: "Open", href: "/admin/profile" } },
        { q: "Browse & book as a customer", a: ["Owners can use Nearest like a student: Account → Switch workspace → Browse & book. Owners' own pro businesses work like every pro (free to join), with no 30-day spot rule — just the ID check and payouts."], link: { label: "Switch workspace", href: "/workspace" } },
      ],
    },
  ];
}

// ---------------------------------------------------------------- Sales reps
function rep(): GuideSection[] {
  return [
    {
      id: "start", title: "Getting started", icon: "sparkle", topics: [
        { q: "What does a Nearest sales rep do?", a: ["You bring beauty professionals onto Nearest by sharing your own sales link. Nearest connects professionals with students looking for affordable beauty services nearby, and joining is free for professionals.", "You're an independent contractor under the Sales Ambassador Agreement you signed — it covers how you represent Nearest and how compensation works."], link: { label: "Read my agreement", href: "/rep/agreement" } },
        { q: "Why do I verify my ID?", a: ["Your links only give you credit after Nearest verifies your ID (a photo of your driver's license or state ID and a selfie). The photos are deleted as soon as you're reviewed. Payouts open once you're verified too."] },
        { q: "Trouble signing in? (\"You are signed out\")", a: ["That means this browser's saved login is out of sync. Make sure your device's date and time are set automatically, then try again. You can also sign in with a 6-digit code sent to your email instead of your password."] },
      ],
    },
    {
      id: "links", title: "Your links & tracking", icon: "link", topics: [
        { q: "Which link do I share?", a: ["Your dashboard has two links. The professional link is the one for your campaigns — every professional signs up on Nearest through it. The student link is only for public places where adults and families can see it; never message or contact anyone under 18."] },
        { q: "How do sign-ups count for me?", a: ["Anyone who taps your link and signs up within 30 days counts for you — even if they sign up later on another device after tapping it once. Link taps are counted too."] },
        { q: "What do the professional statuses mean?", a: ["Started: they made an account but haven't finished their profile — follow up. Profile complete: they submitted their profile and Nearest is reviewing it. Live: approved and showing to students. First booking: they've been booked at least once."] },
        { q: "Where do I see my results?", a: ["Your dashboard shows link taps, total sign-ups, professionals by status, sign-ups by city and by service category, and your most recent sign-ups (professionals by business name; students are never named)."] },
      ],
    },
    {
      id: "campaigns", title: "Running a campaign", icon: "chart", topics: [
        { q: "How does a campaign work?", a: ["Pick a focus area (a city, neighborhood or the area around a beauty or trade school), pick 1–3 service categories, set a timeframe, and share your professional link in every message. The Campaign Guide on your dashboard has a planner, ideas, where to find professionals online and in person, how to approach schools and pros, ads, and copy-ready messages with your link already filled in."], link: { label: "Open the Campaign Guide", href: "/rep#campaign-guide" } },
        { q: "Can I approach schools?", a: ["Yes — beauty, cosmetology, esthetics, nail, barber and trade schools. Talk to adults who run the programs: the director, instructors, career services or job placement, and alumni coordinators. Don't approach high schools, high school staff or high school students for this program; Nearest handles school-district relationships directly."] },
        { q: "Can I run Facebook, Instagram or Google ads?", a: ["Only with Nearest's written approval first, because ads using Nearest's name, logo or trademarks need it (Sales Ambassador Agreement, section 5). Email support@usenearest.com with your plan, ad text, images and budget. Run approved ads from your own page, link them to your professional link, and never bid on the word Nearest. You pay for your own ads."] },
        { q: "How do I follow up with pros who didn't finish?", a: ["Check Professionals by status for anyone in Started. Send the follow-up message from the Campaign Guide, offer to walk them through it, and remind them that services, hours and photos of their work are what's left. Once they submit, Nearest reviews their profile."] },
      ],
    },
    {
      id: "rules", title: "Brand rules", icon: "shield", topics: [
        { q: "What must I always do — and never do?", a: ["Always send professionals to sign up on Nearest through your link. Never tell anyone to list on another app, website or directory.", "Never explain how Nearest makes money — if asked about cost: free to join, no monthly fee, and a booking fee is included in the price clients see.", "Don't center Nearest on one city or state, and don't say who owns Nearest.", "Never promise clients, bookings, income or results. One personal message at a time — no bulk or automated messages. No gifts or money for sign-ups, and never sign people up yourself."] },
      ],
    },
    {
      id: "pay", title: "Getting paid", icon: "wallet", topics: [
        { q: "How do payouts work?", a: ["Set up payouts on your dashboard (Stripe, our payment provider — your bank account or debit card). Any compensation is set by Nearest in writing, and payments show under Payouts with the date and amount. You're responsible for your own taxes; Nearest doesn't withhold taxes."] },
      ],
    },
  ];
}

export async function guideFor(audience: GuideAudience): Promise<GuideSection[]> {
  if (audience === "rep") return rep();
  const r = rules(await getSettings());
  return audience === "student" ? student(r) : audience === "pro" ? pro(r) : admin(r);
}
